UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/CostaBrava.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var sb = new System.Text.StringBuilder();
var garage = UnityEngine.Object.FindObjectOfType<VehicleGarage>();
if (garage == null) return "no garage";
// Apply the HD sports car and measure where the kit ends up relative to the body.
for (int i = 0; i < garage.variants.Length; i++)
{
    if (garage.specIds[i] != "hdSportsCar") continue;
    garage.Apply(i);
    var body = garage.variants[i].root;
    sb.AppendLine("applied " + garage.specIds[i] + " roof=" + garage.ChosenRoof.ToString("F2"));
    var aero = garage.transform.Find("AURORA aero kit");
    var kit = garage.transform.Find("AURORA light kit");
    sb.AppendLine("aero localPos=" + (aero ? aero.localPosition.ToString() : "none") + " active=" + (aero ? aero.gameObject.activeSelf.ToString() : "-"));
    if (aero)
        foreach (Transform t in aero)
            sb.AppendLine("   " + t.name + " localPos=" + t.localPosition + " world=" + t.position);
    if (kit)
        foreach (Transform t in kit)
            sb.AppendLine("   kit " + t.name + " localPos=" + t.localPosition);
    // Body roof in car space.
    float roof = 0f, minZ = 9999f, maxZ = -9999f;
    foreach (Renderer r in body.GetComponentsInChildren<Renderer>())
    {
        if (!r.gameObject.name.ToLowerInvariant().StartsWith("body")) continue;
        var b = r.localBounds; var c = b.center; var e = b.extents;
        for (int k = 0; k < 8; k++)
        {
            Vector3 lp = new Vector3((k & 1) == 0 ? c.x - e.x : c.x + e.x, (k & 2) == 0 ? c.y - e.y : c.y + e.y, (k & 4) == 0 ? c.z - e.z : c.z + e.z);
            Vector3 carLocal = garage.transform.InverseTransformPoint(r.transform.TransformPoint(lp));
            if (carLocal.y > roof) roof = carLocal.y;
            if (carLocal.z < minZ) minZ = carLocal.z;
            if (carLocal.z > maxZ) maxZ = carLocal.z;
        }
    }
    sb.AppendLine("body roofY=" + roof.ToString("F2") + " bodyMinZ=" + minZ.ToString("F2") + " bodyMaxZ=" + maxZ.ToString("F2"));
}
Debug.Log("PROBE7 " + sb.ToString().Replace("\r", "").Replace("\n", " || "));
return sb.ToString();
